"""Authoring source for follow-up (secondary consequence) narrative episodes.

Writes game/data/story/episodes/<CASE-ID>.json for every follow-up case. Follow-ups reuse the local
characters of their parent episode so people remember earlier decisions. All text is FICTIONAL and
describes only the scheduled effects of each choice (see the case files) or the trigger condition.

Run: python3 scripts/story/author_followups.py   (idempotent; review the JSON diff afterwards)
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
EP = ROOT / "game/data/story/episodes"


def B(s, t, e="netral", bg=None):
    b = {"s": s, "e": e, "t": t}
    if bg:
        b["bg"] = bg
    return b


def parent_locals(parent):
    return json.loads((EP / f"{parent}.json").read_text(encoding="utf-8")).get("locals", {})


