def main():
    for cid, d in FOLLOWUPS.items():
        ep = {
            "schema": "nusantara.story_episode/1",
            "case_id": cid,
            "fact_class": "FICTIONAL",
            "parent": d["parent"],
            "background": d["bg"],
            "locals": parent_locals(d["parent"]),
            "agenda": {"hook": d["hook"], "label": "Lanjutan"},
            "opening": d["opening"],
            "reactions": d["reactions"],
            "journal": d["journal"],
        }
        (EP / f"{cid}.json").write_text(json.dumps(ep, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    print("wrote", len(FOLLOWUPS), "follow-up episodes")


if __name__ == "__main__":
    main()
